\set ON_ERROR_STOP on
-- Direct Production connection only. No pooler host is inferred or accepted.
-- Run via the read-only wrapper for preflight/verification with pinned trust.
\getenv release_sslmode PGSSLMODE
\getenv release_rootcert PGSSLROOTCERT
\getenv release_appdata APPDATA
begin isolation level serializable read only;
set local lock_timeout='2s';
set local statement_timeout='30s';
select set_config('menu_man.release_host', :'HOST', true);
select set_config('menu_man.release_user', :'USER', true);
select set_config('menu_man.release_port', :'PORT', true);
select set_config('menu_man.release_project', :'production_project_ref', true);
select set_config('menu_man.release_sslmode', :'release_sslmode', true);
select set_config('menu_man.release_rootcert', :'release_rootcert', true);
select set_config('menu_man.release_appdata', :'release_appdata', true);
do $$ begin
  if current_setting('menu_man.release_project') <> 'fullaiodvmilkdxyxnln'
    or current_setting('menu_man.release_host') <> 'db.fullaiodvmilkdxyxnln.supabase.co'
    or current_setting('menu_man.release_user') <> 'postgres'
    or current_setting('menu_man.release_port') <> '5432'
    or current_database() <> 'postgres' or current_user <> 'postgres'
    or current_setting('menu_man.release_sslmode') <> 'verify-full'
    or btrim(current_setting('menu_man.release_rootcert')) = ''
    or replace(lower(current_setting('menu_man.release_rootcert')),chr(92),'/') <> replace(lower(current_setting('menu_man.release_appdata')),chr(92),'/') || '/postgresql/root.crt'
    or not coalesce((select ssl from pg_stat_ssl where pid=pg_backend_pid()),false)
  then raise exception 'Exact Production identity and verified TLS required'; end if;
end $$;
do $$ declare t text; collision boolean; v_entry record; v_column text; begin
  for v_entry in select key,value from jsonb_each($schema${"restaurants":["id","slug","name","tagline","description","logo_url","hero_image_url","phone","address_line1","city","state","postal_code","timezone","theme_preset","currency","is_active","is_indexable","theme_overrides","primary_domain","pickup_url","doordash_url","google_maps_url","instagram_url","facebook_url","latitude","longitude"],"menus":["id","restaurant_id","name","is_published"],"menu_sections":["id","menu_id","name","description","sort_order","is_active"],"menu_items":["id","restaurant_id","name","description","price_cents","source_system","source_item_id","is_orderable","image_url","source_image_url","image_path"],"menu_section_items":["id","section_id","item_id","sort_order"],"modifier_groups":["id","restaurant_id","name","is_active"],"modifier_options":["id","restaurant_id","modifier_group_id","name","default_price_adjustment_cents","sort_order","is_active","is_default"],"menu_item_modifier_groups":["restaurant_id","menu_item_id","modifier_group_id","min_selections","max_selections","sort_order","is_active"],"restaurant_business_hours":["restaurant_id","day_of_week","open_time","close_time","is_closed","sort_order"],"restaurant_ordering_settings":["restaurant_id","pickup_enabled","asap_enabled","scheduled_pickup_enabled","tax_strategy","tax_rate_basis_points"],"restaurant_notification_settings":["restaurant_id","customer_order_confirmation_email","customer_ready_for_pickup_email","customer_refund_confirmation_email","internal_new_paid_order_email","internal_payment_refund_exception_email","internal_email_recipient"]}$schema$::jsonb) loop
    for v_column in select value from jsonb_array_elements_text(v_entry.value) loop
      if not exists(select 1 from information_schema.columns col where col.table_schema='public' and col.table_name=v_entry.key and col.column_name=v_column)
      then raise exception 'Required column missing: %.%',v_entry.key,v_column; end if;
    end loop;
  end loop;
  if not exists(select 1 from pg_trigger where tgrelid='public.restaurants'::regclass and tgname='restaurants_initialize_notification_settings' and tgenabled='O')
  then raise exception 'Expected notification initialization trigger missing; review Production schema'; end if;
  if exists(select 1 from public.restaurants where lower(slug)='super-tacos' or id='20000000-0000-4000-8000-000000000001'::uuid)
  then raise exception 'Existing restaurant: stop; never adopt, overwrite or rerun'; end if;
  foreach t in array array['restaurants','menus','menu_sections','menu_items','menu_section_items','modifier_groups','modifier_options'] loop
    execute format('select exists(select 1 from public.%I where id::text like ''20000000-0000-4000-8000-%%'')',t) into collision;
    if collision then raise exception 'Reserved identity collision in %',t; end if;
  end loop;
end $$;
select jsonb_build_object('project','fullaiodvmilkdxyxnln','tenant','20000000-0000-4000-8000-000000000001','capturedAt',now(),'otherContent',encode(sha256(convert_to(concat_ws('|',(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.restaurants a where not (id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menus a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menu_sections a where not (menu_id='20000000-0000-4000-8000-000000000002'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menu_items a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menu_section_items a where not (section_id in (select id from public.menu_sections where menu_id='20000000-0000-4000-8000-000000000002'::uuid) or item_id in (select id from public.menu_items where restaurant_id='20000000-0000-4000-8000-000000000001'::uuid))),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.modifier_groups a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.modifier_options a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menu_item_modifier_groups a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.restaurant_business_hours a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.restaurant_ordering_settings a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.restaurant_notification_settings a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid))),'UTF8')),'hex'),'paymentsAndOrders',encode(sha256(convert_to(concat_ws('|',(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.restaurant_payment_connections a where true),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.payment_provider_references a where true),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.payments a where true),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.payment_attempts a where true),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.refunds a where true),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.orders a where true)),'UTF8')),'hex'),'existingSuperTacos',false);
rollback;
